const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});
const text = JSON.stringify(payload).toLowerCase();

// Zero-Trust Non-PHI Check: Reject immediately if clinical PHI terms or patient demographics are present
const phiKeywords = ['prescription', 'diagnosis', 'symptom', 'treatment plan', 'blood test', 'biopsy', 'radiology', 'mri scan', 'ehr record', 'patient record', 'hiv', 'oncology', 'doctor notes', 'vitals', 'clinical_notes', 'patient_name', 'patientid', 'mrn', 'dob', 'birth_date', 'aadhaar', 'ssn', 'icd10', 'rx', 'lab_result'];
const containsPhi = phiKeywords.some(keyword => text.includes(keyword));

const facilityId = String(payload.facilityId || payload.facility_id || '').trim();
const facilityName = String(payload.facilityName || payload.hospitalName || 'Hospital Facility').trim();
const department = String(payload.department || payload.unit || 'Emergency / ICU').trim();
const totalBeds = Number(payload.totalBeds || payload.bedCapacity || 0);
const occupiedBeds = Number(payload.occupiedBeds || payload.currentOccupancy || 0);
const availableBeds = Number(payload.availableBeds !== undefined ? payload.availableBeds : Math.max(0, totalBeds - occupiedBeds));
const occupancyRate = totalBeds > 0 ? Math.round((occupiedBeds / totalBeds) * 100) : Number(payload.occupancyRate || 0);
const threshold = Number(payload.threshold || 90);

let surgeLevel = 'NORMAL';
if (occupancyRate >= 95) {
  surgeLevel = 'CRITICAL_SURGE';
} else if (occupancyRate >= 90) {
  surgeLevel = 'HIGH_SURGE';
} else if (occupancyRate >= 80) {
  surgeLevel = 'ELEVATED';
}

const isValidCapacity = Boolean(facilityId && totalBeds > 0 && !containsPhi);
const isSurgeAlert = Boolean(isValidCapacity && occupancyRate >= threshold);

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    containsPhi,
    isValidCapacity,
    isSurgeAlert,
    capacity: {
      facilityId,
      facilityName,
      department,
      totalBeds,
      occupiedBeds,
      availableBeds,
      occupancyRate,
      threshold,
      surgeLevel,
      timestamp: new Date().toISOString()
    }
  }
}];

const item = $input.first().json;
const cap = item.capacity;

const diversionAction = cap.occupancyRate >= 95
  ? 'EMERGENCY_DIVERSION_ACTIVATED: Inbound ambulances rerouted to secondary network facility; on-call triage staff dispatched.'
  : 'CAPACITY_SURGE_WARNING: Standby bed turnover team mobilized; elective admissions paused.';

const alertNotification = {
  title: `🚨 [${cap.surgeLevel}] Bed Capacity Alert — ${cap.facilityName} (${cap.department})`,
  facilityId: cap.facilityId,
  department: cap.department,
  occupancyRate: `${cap.occupancyRate}%`,
  bedTelemetry: {
    totalBeds: cap.totalBeds,
    occupiedBeds: cap.occupiedBeds,
    availableBeds: cap.availableBeds
  },
  protocolExecuted: diversionAction,
  recipientGroup: 'Hospital Duty Operations Coordinator & Inpatient Bed Manager',
  complianceBoundary: 'Zero-Trust Non-PHI Aggregate Capacity Perimeter'
};

return [{
  json: {
    eventId: item.eventId,
    status: 'capacity_alert_dispatched',
    detail: {
      facilityId: cap.facilityId,
      department: cap.department,
      occupancyRate: cap.occupancyRate,
      surgeLevel: cap.surgeLevel,
      alertNotification,
      alertedAt: new Date().toISOString()
    }
  }
}];

const item = $input.first().json;
return [{
  json: {
    eventId: item.eventId,
    status: 'capacity_alert_rejected',
    detail: {
      error: item.containsPhi
        ? 'CRITICAL_SECURITY_BREACH: Prohibited PHI clinical data detected in capacity telemetry'
        : 'Invalid capacity telemetry: missing facilityId or totalBeds must be greater than zero'
    }
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'processed',
  detail: item.json.detail || {}
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
